(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = { path: location.pathname, url: location.origin };
  if (!document.querySelector('.pj-title')) {
    const cards = [...document.querySelectorAll('.tb-project-main')];
    if (cards[0]) { cards[0].click(); await sleep(3000); }
  }
  out.title = document.querySelector('.pj-title')?.textContent || null;
  // 钩住 createObjectURL，留下导出的 .ecp 字节（真实导出路径）
  let captured = null;
  const orig = URL.createObjectURL.bind(URL);
  URL.createObjectURL = (blob) => { captured = blob; return orig(blob); };
  const btn = [...document.querySelectorAll('.pj-head-actions > button')].find((b) => b.textContent.includes('保存作品文件'));
  out.hasButton = !!btn;
  btn?.click();
  await sleep(4000);
  URL.createObjectURL = orig;
  if (!captured) { out.exported = false; out.notice = document.querySelector('.tb-ok')?.textContent || null; return JSON.stringify(out); }
  const buf = new Uint8Array(await captured.arrayBuffer());
  const text = new TextDecoder('latin1').decode(buf);
  out.exported = true;
  out.size = captured.size;
  out.zipHead = Array.from(buf.slice(0, 4)).map((b) => b.toString(16).padStart(2, '0')).join(' ');
  out.entries = [...new Set([...text.matchAll(/(?:manifest|components|sections|images|thumbnail)[A-Za-z0-9_./-]*\.(?:json|jpg|png|txt)/g)].map((m) => m[0]))];
  out.leaksKey = /sk-[A-Za-z0-9]|apiKey|api_key|ai_config/.test(text);
  return JSON.stringify(out);
})()
